pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IOracleProviderMinimal {
    struct OracleVersion { uint256 version; uint256 timestamp; int256 price; }
    function setVersion(uint256 v, uint256 ts, int256 p) external;
    function currentVersion() external view returns (OracleVersion memory);
}

// Minimal oracle that allows setting arbitrary price to exercise transform difference
contract DummyOracle is IOracleProviderMinimal {
    OracleVersion internal _v;
    function setVersion(uint256 v, uint256 ts, int256 p) external {
        _v.version = v;
        _v.timestamp = ts;
        _v.price = p;
    }
    function currentVersion() external view returns (OracleVersion memory) {
        return _v;
    }
}

contract InvMutTest is Test {
    C c;
    DummyOracle oracle;

    function setUp() public {
        c = new C();
        oracle = new DummyOracle();
    }

