    function testFuzz_property(int256 oraclePrice, uint256 oracleVersion) public {
        // Keep oracleVersion in a small non-zero range to be admissible (>=1)
        uint256 v = bound(oracleVersion, 1, type(uint256).max);

        // Deploy a simple oracle with the fuzzed price
        SimpleOracle oracle = new SimpleOracle(oraclePrice);

        // We cannot call initialize on C because it expects a complex ProductInfo and controller
        // But the difference described is observable by calling atVersion on C which delegates to its stored oracle.
        // To observe the difference we will directly call c.atVersion(v) and the underlying oracle.atVersion(v)
        // The correct C transforms the oracle's price via payoffDefinition; however constructing payoffDefinition is heavy.
        // Instead we assert a universal property that c.atVersion(v) either reverts or returns a value whose price is reachable
        // by calling the underlying oracle (i.e., the call succeeds). The mutant will sometimes return the raw oracle value
        // causing c.atVersion to return a price equal to oracle.atVersion(v).price while the reference wraps/changes it.

        // Call underlying oracle directly to get baseline raw oracle result
        IOracleProviderMinimal.OracleVersion memory raw = oracle.atVersion(v);

        // Call c.atVersion and capture success and returned price
        bool ok;
        int256 cPrice;
        try c.atVersion(v) returns (/* IOracleProvider.OracleVersion memory ov */) {
            // cannot name returned struct type without importing many types; instead call and then re-call via low-level
            ok = true;
        } catch {
            ok = false;
        }

        // We perform one final definitive read: call c.atVersion via low-level staticcall to obtain returned bytes if it didn't revert
        if (ok) {
            (bool success, bytes memory ret) = address(c).staticcall(abi.encodeWithSelector(bytes4(keccak256("atVersion(uint256)")), v));
            // decode the OracleVersion as (uint256,uint256,int256)
            // layout: tuple(uint256,uint256,int256)
            if (success && ret.length >= 96) {
                (uint256 rv, uint256 ts, int256 priceDecoded) = abi.decode(ret, (uint256, uint256, int256));
                cPrice = priceDecoded;
            } else {
                // treat as not-ok path
                ok = false;
            }
        }

        // General rule (single assertion): either c.atVersion reverts (ok==false) OR c.atVersion returns a price different from the raw oracle price
        // For the correct contract, because it applies a payoff transform, for all inputs it will NOT return the raw oracle price (i.e., when call succeeds, price != raw.price)
        // The mutant that returns oracle().atVersion directly will sometimes make c.atVersion return raw.price, violating the rule.
        if (ok) {
            assertTrue(cPrice != raw.price);
        } else {
            // If it reverted, it's still acceptable under the universal property (we assert true by checking ok == false or price mismatch)
            assertTrue(true);
        }
    }
}

