// Helper that will perform delegatecall into target to store a uint256 at a given slot in the caller's storage (i.e., target's storage when delegated into)
contract Writer {
    // perform a delegatecall into target that will execute code in this contract to store the slot
    function doDelegateStore(address target, bytes32 slot, uint256 value) public {
        // build calldata for this contract's delegateStore(bytes32,uint256)
        bytes memory payload = abi.encodeWithSelector(this.delegateStore.selector, slot, value);
        // delegatecall into target so that sstore happens in target's storage
        (bool ok, ) = target.delegatecall(payload);
        require(ok, "delegate store failed");
    }

    // function that will be executed via delegatecall into target; it performs sstore(slot, value)
    function delegateStore(bytes32 slot, uint256 value) public {
        assembly { sstore(slot, value) }
    }
}

