pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the pendingMakerFee value and a boolean flag indicating whether to set a pending update
    function testFuzz_property(uint64 pendingMakerFee, bool makePending) public {
        // We need to initialize contract C so that its initializer path sets up storages used by makerFee.
        // Contract expects initialize(ProductInfo) via msg.sender being controller in __UControllerProvider__initialize.
        // Simulate by calling initialize while impersonating a controller that is a contract and sets owner/coordinator behavior.
        // We'll deploy a minimal fake controller that implements only the methods used by initialization and makerFee paths.
        FakeController controller = new FakeController(address(this));
        // initialize product info with sensible defaults
        C.ProductInfo memory info;
        info.name = "p";
        info.symbol = "s";
        info.payoffDefinition = C.PayoffDefinition({payoffType: C.PayoffDefinitionLib.PayoffType(0), payoffDirection: C.PayoffDefinitionLib.PayoffDirection(0), data: bytes30(0)});
        info.oracle = IOracleProvider(address(new FakeOracle()));
        info.maintenance = UFixed18.wrap(0);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(1e18); // store maker fee = 1.0
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(0);
        info.utilizationCurve = C.JumpRateUtilizationCurve({minRate: PackedFixed18.wrap(0), maxRate: PackedFixed18.wrap(0), targetRate: PackedFixed18.wrap(0), targetUtilization: PackedUFixed18.wrap(0)});

        // Impersonate controller to call initialize
        vm.prank(address(controller));
        c.initialize(info);

        // By construction, the correct contract's makerFee() must equal the stored committed maker fee (1e18 wrapped).
        // Now optionally set pending maker fee via direct interaction with the pending fee storage accessor: use updateMakerFee when product owner calls it.
        // FakeController will mark msg.sender as owner for coordinator 0. So use vm.prank(owner) to call updateMakerFee.
        // Bound the pendingMakerFee to a plausible uint64 (it already is uint64). Use provided boolean to decide.
        if (makePending) {
            // craft a pending fee value by calling updateMakerFee through the owner; this will either set immediate or pending depending on product state
            vm.prank(controller.owner());
            // call updateMakerFee with a UFixed18 wrapping the fuzzed pendingMakerFee scaled into 1e18 base
            // To avoid making value > 2^64, we convert uint64 pendingMakerFee into UFixed18 via UFixed18.wrap(uint256(pendingMakerFee))
            c.updateMakerFee(UFixed18.wrap(uint256(pendingMakerFee)));
        }

        // Read makerFee via external getter; this must return the committed stored value on the reference contract for all inputs.
        // If the mutant returns the pending value when pending.makerFeeUpdated is set, it will diverge for some inputs.
        UFixed18 got;
        try c.makerFee() returns (UFixed18 v) {
            got = v;
        } catch {
            // If call reverted, treat as failure of property (but reference shouldn't revert here)
            assertTrue(false);
            return;
        }

        // The committed stored maker fee we set at initialization was UFixed18.wrap(1e18)
        assertTrue(got == UFixed18.wrap(1e18));
    }
}

// Minimal fake controller and oracle to satisfy initialize requirements.
interface IOracleProvider {
    struct OracleVersion { uint256 version; uint256 timestamp; C.Fixed18 price; }
    function currentVersion() external view returns (OracleVersion memory);
    function atVersion(uint256 oracleVersion) external view returns (OracleVersion memory);
    function sync() external returns (OracleVersion memory);
}

contract FakeOracle is IOracleProvider {
    function currentVersion() external pure returns (OracleVersion memory) {
        return OracleVersion({version: 1, timestamp: block.timestamp, price: C.Fixed18.wrap(0)});
    }
    function atVersion(uint256) external pure returns (OracleVersion memory) {
        return OracleVersion({version: 1, timestamp: block.timestamp, price: C.Fixed18.wrap(0)});
    }
    function sync() external pure returns (OracleVersion memory) {
        return OracleVersion({version: 1, timestamp: block.timestamp, price: C.Fixed18.wrap(0)});
    }
}

interface IControllerMinimal {
    function owner() external view returns (address);
    function owner(uint256) external view returns (address);
    function coordinatorFor(C) external view returns (uint256);
}

contract FakeController is IControllerMinimal {
    address public immutable _owner;
    constructor(address owner_) { _owner = owner_; }
    function owner() external view returns (address) { return _owner; }
    function owner(uint256) external view returns (address) { return _owner; }
    function coordinatorFor(C) external pure returns (uint256) { return 0; }
}

